/* A slower SQL refresher, inserted before existing lessons without replacing IDs. */
(() => {
 const C=window.TECHPATH,bank=window.TECHPATH_CHALLENGES,T=bank.tables;
 const customers=T.Customers.rows,orders=T.Orders.rows,payments=T.Payments.rows;
 const paid=orders.filter(r=>r[3]==='Paid'),success=payments.filter(r=>r[3]==='Succeeded');
 const sorted=[...orders].sort((a,b)=>b[4]-a[4]||a[0]-b[0]);
 const totals=success.map(p=>[p[1],p[4]]); // Seed has one Succeeded payment per order; task handles many.
 const stages=['Chọn và lọc dữ liệu','Ghép điều kiện & sắp xếp','NULL & biểu thức','Gom nhóm từng bước','Làm quen JOIN'];
 const specs=[
  ['select-customers','Chọn hai cột từ Customers','Customers','Lấy customer_id và customer_name của tất cả khách hàng. Chưa cần lọc hoặc sắp xếp.','SELECT customer_id, customer_name FROM dbo.Customers;',['customer_id','customer_name'],customers.map(r=>r.slice(0,2)),'SELECT chọn những cột muốn đọc; FROM cho biết bảng chứa chúng. Hôm nay chỉ chọn cột, chưa cần JOIN.','Bạn cần tên hai cột nào sau SELECT?','Chỉ viết tên cột, cách nhau bằng dấu phẩy; FROM đứng trước tên bảng.'],
  ['select-orders','Đọc đơn hàng, chọn đúng thông tin','Orders','Lấy order_id, order_status, order_total của tất cả đơn hàng. Không dùng SELECT *.','SELECT order_id, order_status, order_total FROM dbo.Orders;',['order_id','order_status','order_total'],orders.map(r=>[r[0],r[3],r[4]]),'Một dòng Orders là một đơn hàng. Chọn đúng cột giúp đọc kết quả dễ hơn. Lặp lại SELECT trên một bảng khác trước khi thêm điều kiện.','Đề cần ba cột nào, theo thứ tự nào?','Đừng dùng tên cột của Customers trong query chỉ đọc Orders.'],
  ['where-paid','WHERE: chỉ lấy đơn Paid','Orders',"Lấy order_id, order_total của các đơn có order_status = 'Paid'.", "SELECT order_id, order_total FROM dbo.Orders WHERE order_status = 'Paid';",['order_id','order_total'],paid.map(r=>[r[0],r[4]]),'WHERE giữ các dòng thỏa điều kiện. Chuỗi như Paid cần đặt trong dấu nháy đơn. Chỉ dùng một điều kiện trong bài này.','Cột nào mô tả trạng thái của đơn?','WHERE nằm sau FROM. Điều kiện so sánh dùng dấu =.'],
  ['where-amount','WHERE: so sánh số tiền','Orders','Lấy order_id, order_total của mọi đơn có order_total > 100. Không lọc trạng thái.', 'SELECT order_id, order_total FROM dbo.Orders WHERE order_total > 100;',['order_id','order_total'],orders.filter(r=>r[4]>100).map(r=>[r[0],r[4]]),'So sánh số dùng >, <, >=, <=. Điều kiện > 100 không giữ giá trị đúng bằng 100. Không thêm rule chưa được yêu cầu.','Bạn đang so sánh giá trị ở cột nào?','Số 100 không cần dấu nháy.'],
  ['where-and','AND: hai điều kiện cùng đúng','Orders',"Lấy order_id, order_total của đơn vừa Paid, vừa có order_total > 100.","SELECT order_id, order_total FROM dbo.Orders WHERE order_status = 'Paid' AND order_total > 100;",['order_id','order_total'],paid.filter(r=>r[4]>100).map(r=>[r[0],r[4]]),'AND yêu cầu cả hai điều kiện đều đúng trên cùng một dòng. Ôn cách lọc trước khi xử lý dữ liệu nhiều bảng.','Từ “vừa … vừa …” tương ứng với AND hay OR?','Ghép hai biểu thức so sánh hoàn chỉnh bằng AND.'],
  ['where-or','OR: một trong hai trạng thái','Orders',"Lấy order_id, order_status của đơn Pending hoặc Cancelled.","SELECT order_id, order_status FROM dbo.Orders WHERE order_status = 'Pending' OR order_status = 'Cancelled';",['order_id','order_status'],orders.filter(r=>['Pending','Cancelled'].includes(r[3])).map(r=>[r[0],r[3]]),'OR giữ dòng khi ít nhất một điều kiện đúng. Mỗi vế cần có phép so sánh; viết một chuỗi trơ sau OR chưa phải điều kiện.','Một dòng có cần đồng thời Pending và Cancelled không?','Có thể viết hai so sánh nối bởi OR, hoặc dùng IN với danh sách hai giá trị.'],
  ['order-by','ORDER BY: sắp xếp rõ ràng','Orders','Lấy order_id, order_total của mọi đơn; sắp xếp order_total giảm dần, nếu bằng nhau thì order_id tăng dần.','SELECT order_id, order_total FROM dbo.Orders ORDER BY order_total DESC, order_id ASC;',['order_id','order_total'],sorted.map(r=>[r[0],r[4]]),'ORDER BY quyết định thứ tự hiển thị. DESC giảm dần, ASC tăng dần. Dòng không mặc nhiên có thứ tự nếu không viết ORDER BY.','Cột ưu tiên sắp xếp đầu tiên là gì?','Hai tiêu chí trong ORDER BY cách nhau bằng dấu phẩy.'],
  ['top','TOP: lấy ba đơn lớn nhất','Orders','Lấy 3 đơn có order_total lớn nhất: order_id, order_total. Sắp xếp tổng giảm dần, rồi order_id tăng dần.','SELECT TOP (3) order_id, order_total FROM dbo.Orders ORDER BY order_total DESC, order_id ASC;',['order_id','order_total'],sorted.slice(0,3).map(r=>[r[0],r[4]]),'Trong SQL Server, TOP giới hạn số dòng. Muốn “lớn nhất”, cần sắp xếp trước khi lấy TOP; TOP một mình không chứng minh được điều đó.','Bạn đã chỉ rõ tiêu chí “lớn nhất” chưa?','TOP (3) đứng sau SELECT, còn ORDER BY ở cuối query.'],
  ['null','IS NULL: tìm email thiếu','Customers','Lấy customer_id, customer_name của khách có email NULL.','SELECT customer_id, customer_name FROM dbo.Customers WHERE email IS NULL;',['customer_id','customer_name'],customers.filter(r=>r[2]===null).map(r=>r.slice(0,2)),'NULL là chưa có giá trị, không phải chuỗi chữ NULL. Kiểm tra dữ liệu thiếu bằng IS NULL, không dùng = NULL.','Email thiếu được biểu diễn bằng NULL hay chuỗi rỗng trong dataset?','Điều kiện cần đọc là “email IS NULL”.'],
  ['not-null','IS NOT NULL: email đã có','Customers','Lấy customer_id, email của khách có email khác NULL. Chưa cần loại email trùng.','SELECT customer_id, email FROM dbo.Customers WHERE email IS NOT NULL;',['customer_id','email'],customers.filter(r=>r[2]!==null).map(r=>[r[0],r[2]]),'IS NOT NULL giữ những dòng đã có giá trị. Giá trị có mặt chưa chứng minh nó duy nhất hoặc hợp lệ về nghiệp vụ.','Bài này cần kiểm tra có email, hay kiểm tra email duy nhất?','Đảo điều kiện IS NULL bằng IS NOT NULL.'],
  ['expression','Biểu thức: tính thêm một cột','Orders','Lấy order_id, order_total và discount_amount = order_total * 0.10 cho mọi đơn Paid. Không thay đổi dữ liệu.','SELECT order_id, order_total, order_total * 0.10 AS discount_amount FROM dbo.Orders WHERE order_status = \'Paid\';',['order_id','order_total','discount_amount'],paid.map(r=>[r[0],r[4],r[4]*.1]),'Một biểu thức trong SELECT tạo giá trị hiển thị; không cập nhật bảng. AS đặt tên cột để output khớp yêu cầu.','Cần tính trên từng dòng hay cộng nhiều dòng?','Viết phép nhân trong SELECT và đặt alias discount_amount.'],
  ['case','CASE: gán nhãn đơn giản','Orders',"Lấy order_id, payment_flag; Paid → 'Da thanh toan', mọi trạng thái khác → 'Chua xac nhan'. Chỉ dựa trên order_status.","SELECT order_id, CASE WHEN order_status = 'Paid' THEN 'Da thanh toan' ELSE 'Chua xac nhan' END AS payment_flag FROM dbo.Orders;",['order_id','payment_flag'],orders.map(r=>[r[0],r[3]==='Paid'?'Da thanh toan':'Chua xac nhan']),'CASE WHEN kiểm tra điều kiện; THEN là giá trị khi đúng, ELSE khi không đúng; END kết thúc biểu thức. Đây chỉ là nhãn theo Orders, chưa đối chiếu Payments.','Điều kiện nào quyết định nhãn thứ nhất?','Khung: CASE WHEN điều_kiện THEN giá_trị ELSE giá_trị END AS tên_cột.'],
  ['count','COUNT: đếm đơn Paid','Orders','Trả một cột order_count, một dòng: số đơn có trạng thái Paid.','SELECT COUNT(*) AS order_count FROM dbo.Orders WHERE order_status = \'Paid\';',['order_count'],[[paid.length]],'COUNT(*) đếm số dòng sau khi lọc. Khi không GROUP BY, phép đếm tạo một giá trị cho cả tập dữ liệu.','Cần lọc Paid trước hay đếm tất cả rồi tự trừ?','WHERE lọc tập dòng; COUNT(*) nằm trong SELECT.'],
  ['sum','SUM: cộng tiền trên một bảng','Orders','Trả một cột total_paid, một dòng: tổng order_total của mọi đơn Paid. Chưa dùng Payments.','SELECT SUM(order_total) AS total_paid FROM dbo.Orders WHERE order_status = \'Paid\';',['total_paid'],[[paid.reduce((n,r)=>n+r[4],0)]],'SUM cộng các giá trị. Ở đây tổng tiền đơn đã đánh dấu Paid khác với tiền thực thu từ Payments; hãy đọc đúng nguồn cần dùng.','Cột số tiền được yêu cầu nằm ở bảng nào?','Dùng SUM với order_total, không dùng COUNT.'],
  ['group-count','GROUP BY: đếm theo trạng thái','Orders','Trả order_status, order_count: số đơn ở mỗi trạng thái. Không cần sắp xếp.','SELECT order_status, COUNT(*) AS order_count FROM dbo.Orders GROUP BY order_status;',['order_status','order_count'],['Paid','Pending','Cancelled'].map(s=>[s,orders.filter(r=>r[3]===s).length]),'GROUP BY tạo các nhóm cùng giá trị. Mỗi dòng output bây giờ là một trạng thái, không còn là một đơn hàng.','Mỗi dòng kết quả cần đại diện cho một đơn hay một trạng thái?','Cột phân nhóm xuất hiện trong SELECT và GROUP BY.'],
  ['group-payments','SUM theo order_id: cộng từng đơn','Payments','Trả order_id, total_payment: tổng payment_amount của payment Succeeded theo từng order. Chỉ xét Payments.','SELECT order_id, SUM(payment_amount) AS total_payment FROM dbo.Payments WHERE payment_status = \'Succeeded\' GROUP BY order_id;',['order_id','total_payment'],totals,'Tách việc cộng payment thành một bài riêng. Trước hết lọc Succeeded, sau đó gom theo order_id và cộng tiền. Chưa cần JOIN hoặc so sánh Orders.','Tập payment nào được phép góp vào tổng?','WHERE lọc trạng thái; GROUP BY order_id tạo một dòng cho từng đơn.'],
  ['having','HAVING: lọc sau khi cộng','Payments','Từ tổng payment Succeeded theo order, chỉ giữ tổng >= 150. Trả order_id, total_payment.','SELECT order_id, SUM(payment_amount) AS total_payment FROM dbo.Payments WHERE payment_status = \'Succeeded\' GROUP BY order_id HAVING SUM(payment_amount) >= 150;',['order_id','total_payment'],totals.filter(r=>r[1]>=150),'WHERE lọc từng payment trước khi cộng; HAVING lọc các nhóm sau khi đã tính SUM. Bài này chỉ thêm một điều kiện vào bài trước.','Điều kiện >= 150 áp dụng từng payment hay tổng của nhóm?','Viết biểu thức SUM(...) trong HAVING thay vì đặt nó trong WHERE.'],
  ['inner-join','INNER JOIN: lấy tên khách của đơn','Orders,Customers','Trả order_id, customer_name cho các đơn ghép được với khách hàng. Ghép qua customer_id, không yêu cầu sắp xếp.','SELECT o.order_id, c.customer_name FROM dbo.Orders AS o INNER JOIN dbo.Customers AS c ON o.customer_id = c.customer_id;',['order_id','customer_name'],orders.filter(o=>customers.some(c=>c[0]===o[1])).map(o=>[o[0],customers.find(c=>c[0]===o[1])[1]]),'INNER JOIN chỉ giữ dòng có đối tác khớp. Alias o và c giúp phân biệt bảng. Hai bảng liên hệ qua customer_id, không phải order_id.','Cột nào có mặt ở cả hai bảng và thể hiện người đặt đơn?','So sánh o.customer_id với c.customer_id trong ON.'],
  ['left-join','LEFT JOIN: giữ đơn thiếu khách','Orders,Customers','Trả order_id, customer_name cho TẤT CẢ đơn, kể cả đơn không có khách tương ứng. Không lọc NULL.','SELECT o.order_id, c.customer_name FROM dbo.Orders AS o LEFT JOIN dbo.Customers AS c ON o.customer_id = c.customer_id;',['order_id','customer_name'],orders.map(o=>[o[0],customers.find(c=>c[0]===o[1])?.[1]??null]),'LEFT JOIN giữ toàn bộ bảng bên trái. Nếu không có customer khớp, tên khách hiện NULL. Chỉ thay một loại JOIN từ bài trước để quan sát sự khác biệt.','Bảng nào chứa toàn bộ các dòng cần giữ?','Đơn 1006 phải còn, dù customer 99 không tồn tại.'],
  ['join-filter','ON: chỉ ghép payment thành công','Orders,Payments','Trả order_id, payment_id cho mọi đơn Paid. Chỉ ghép payment Succeeded; nếu không có thì payment_id là NULL. Chưa lọc ra đơn thiếu payment.','SELECT o.order_id, p.payment_id FROM dbo.Orders AS o LEFT JOIN dbo.Payments AS p ON o.order_id = p.order_id AND p.payment_status = \'Succeeded\' WHERE o.order_status = \'Paid\';',['order_id','payment_id'],paid.flatMap(o=>{const found=success.filter(p=>p[1]===o[0]);return found.length?found.map(p=>[o[0],p[0]]):[[o[0],null]];}),'Ôn từng vai trò: ON quyết định payment nào được ghép; WHERE chọn đơn Paid. Đây là bước cầu nối trước bài tìm đơn thiếu payment và bài đối soát.','Muốn giữ đơn không có payment, điều kiện Succeeded nên lọc việc ghép hay loại dòng sau JOIN?','Đặt điều kiện của payment trong ON, điều kiện trạng thái đơn trong WHERE.']
 ];
 const lessons=specs.map((s,i)=>{
  const [slug,title,tables,task,solution,columns,rows,concept,hint1,hint2]=s,id='sql-basic-'+slug;
  const stage=stages[Math.floor(i/4)],minutes=i<12?12:i<17?15:18;
  const l={id,module:'sql',title,minutes,summary:concept.split('. ')[0]+'.',body:`<p>${concept}</p><p>Làm chậm: xác định bảng → cột cần trả → điều kiện → viết query → Run để quan sát → Submit. Chưa cần tối ưu hoặc viết nhiều cách.</p>`,task,hints:[hint1,hint2,'Đối chiếu tên cột trong output với đề, rồi chạy từng phần nhỏ.'],solution,expected:rows.length+' dòng; các cột: '+columns.join(', ')+'.',checks:['Đọc đúng bảng và cột.','Giải thích được phép lọc hoặc phép tính đang dùng.'],transfer:'Tự đổi một điều kiện hoặc một cột của bài này; dự đoán kết quả trước khi chạy. Bài chuyển giao có thể hỏi gia sư review.',resources:[],prior:false,foundation:true,foundationIndex:i+1,stage,ordered:['order-by','top'].includes(slug)};
  bank.problems[id]={context:'Ôn nền '+(i+1)+'/20 · '+stage+'. '+concept,tables:tables.split(','),output:columns.join(', ')+'. '+(l.ordered?'Giữ đúng thứ tự đã yêu cầu.':'Không yêu cầu thứ tự dòng.'),rules:['Chỉ làm đúng yêu cầu nhỏ của bài này.','Chỉ SELECT; không sửa dữ liệu hoặc tạo procedure.','Trả đúng tên và thứ tự các cột trong Output Format.'],samples:[{columns,rows}],explanation:'Với dataset gốc, kết quả có '+rows.length+' dòng. '+(i<12?'Đối chiếu từng dòng trong tab Dữ liệu để tự kiểm tra điều kiện.':'Xác định mỗi dòng output đại diện cho điều gì trước khi so sánh.')};
  return l;
 });
 C.lessons=[...lessons,...C.lessons];C.foundationIds=lessons.map(l=>l.id);
})();
